"use client";

import { useState, useEffect } from "react";
import { useSubmit } from "@/components/finance/FormModal";
import { useFinanceData } from "@/lib/api";
import { Card, Skeleton } from "@/components/finance";
import { Empty } from "@/components/finance/Skeleton";

const InvestmentsPage = () => {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  const submit = useSubmit();

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await useFinanceData("/finance/investments");
        if (response.state === "ok") {
          setData(response.data);
        } else {
          setError(response.error);
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) return <Skeleton />;
  if (error) return <Empty message={error} />;

  return (
    <div className="flex flex-col gap-4">
      <Card title="Holdings">
        <table>
          <thead>
            <tr>
              <th>Asset</th>
              <th>Units</th>
              <th>Price</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {data.holdings.map((holding) => (
              <tr key={holding.id}>
                <td>{holding.asset}</td>
                <td>{holding.units}</td>
                <td>{holding.price}</td>
                <td>
                  <button onClick={() => submit(`/finance/investments/${holding.id}`, { method: "PUT" })}>Edit</button>
                  <button onClick={() => submit(`/finance/investments/${holding.id}/archive`, { method: "PUT" })}>Archive</button>
                  {holding.lots_count === 0 && <button onClick={() => submit(`/finance/investments/${holding.id}`, { method: "DELETE" })}>Delete</button>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
      <Card title="Quality">
        {/* Quality panel content */}
      </Card>
      <Card title="Research">
        {/* Research drawer content */}
      </Card>
      <Card title="Visuals">
        {/* Visuals content */}
      </Card>
    </div>
  );
};

export default InvestmentsPage;
